tool_calls.arguments:
{"command":"cd /tmp && cat > app-fixed.json <<'EOF'
{
  "apiVersion": "apps/v1",
  "kind": "Deployment",
  "metadata": { "name": "app", "namespace": "default" },
  "spec": {
    "replicas": 3,
    "template": {
      "metadata": { "labels": { "app": "app" } },
      "spec": {
        "ownerReferences": [
          {
            "apiVersion": "v1",
            "kind": "ConfigMap",
            "name": "app-config"
          }
        ]
      }
    }
  }
}
EOF
kubectl delete deployment app -n default --wait=true 2>&1
sleep 2; kubectl replace -f app-fixed.json -n default --force 2>&1; echo "=== DEPLOY ==="; kubectl get deploy app -n default -o jsonpath='{.metadata.uid}{"\n"}{.metadata.namespace}{"\n"}{.spec.replicas}{"\n"}{.status.updatedReplicas}{"/"}{.status.readyReplicas}{"/"}{.status.availableReplicas}{"/"}{.status.unavailableReplicas}{"/"}{.status.conditions[?(@.type=="Available")].status}{"/"}{.status.conditions[?(@.type=="Progressing")].status}{"/"}{.metadata.generation}{"\n"}'"}

{"command":"cd /tmp && cat > app-fixed-empty.json <<'EOF'
{
  "apiVersion": "apps/v1",
  "kind": "Deployment",
  "metadata": { "name": "app", "namespace": "default" },
  "spec": {
    "replicas": 3,
    "template": {
      "metadata": { "labels": { "app": "app" } },
      "spec": { "ownerReferences": [] }
    }
  }
}
EOF
kubectl delete deployment app -n default --wait=true 2>&1
sleep 2; kubectl apply -f app-fixed-empty.json 2>&1; echo "=== DEPLOY ==="; kubectl get deploy app -n default; echo "=== PODS ==="; kubectl get pods -n default -l app=app"}

{"command":"cd /tmp && kubectl delete pod -l app=app --wait=true 2>&1; echo "pods deleted"; sleep 5; kubectl get pods -n default -l app=app -o jsonpath='{range .items[*]}{.metadata.name}{" ownerRefs="}{.metadata.ownerReferences}{"\n"}{end}'
echo "--- cm ownerRef unchanged ---"; kubectl get cm app-config -n default -o jsonpath='{.metadata.ownerReferences}{"\n"}'
echo "--- config ---"; kubectl exec -n default deploy/app -- cat /etc/config.yaml 2>/dev/null || (kubectl exec -n default deploy/app -- curl -s -o /dev/null -w 'http:%{http_code}\n' https://kubernetes.default.svc/api/v1/namespaces/default/configmaps/app-config || true)
echo "--- check via API server --"; kubectl get configmap app-config -n default -o jsonpath='{.metadata.ownerReferences}{"\n"}'"}

